/*
 * A316991  Numbers m such that 1 < gcd(m, 14) < m and m does not divide 14^e
 *          for e >= 0.
 * https://oeis.org/A316991
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 129, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This sequence is generated by filtering integers m>1 that satisfy:
   1) 1 < gcd(m,14) < m   (i.e., m shares a factor 2 or 7 with 14)
   2) m does not divide 14^e for any e≥0.
   Condition (2) is equivalent to requiring that m has any prime factor other than 2 or 7.
   The implementation performs a linear search, caching results between calls. */

#include <stdlib.h>

static seq_t *cache = NULL;
static size_t cap   = 0;
static size_t len   = 0;

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* safety guard, offset is 1 */

    /* Expand cache to contain at least n terms */
    size_t needed = (size_t)n;
    if (needed > len) {
        if (cap < needed) {
            size_t newcap = cap ? cap * 2 : 1;
            if (newcap < needed) newcap = needed;
            seq_t *p = (seq_t *)realloc(cache, newcap * sizeof(seq_t));
            if (!p) abort();      /* memory allocation failure */
            cache = p;
            cap   = newcap;
        }

        /* Start scanning integers from the last cached value + 1 */
        seq_t m = (len == 0) ? (seq_t)2 : cache[len - 1] + 1;
        for (; len < needed; ++m) {
            /* m must share a factor 2 or 7 with 14 */
            if ((m % (seq_t)2 == 0) || (m % (seq_t)7 == 0)) {
                /* Remove all 2's and 7's from m */
                seq_t t = m;
                while (t % (seq_t)2 == 0) t /= (seq_t)2;
                while (t % (seq_t)7 == 0) t /= (seq_t)7;
                /* If a prime factor other than 2 or 7 remains, keep m */
                if (t > (seq_t)1) {
                    cache[len++] = m;
                }
            }
        }
    }

    return cache[(size_t)n - 1];
}
